struct ManagedResource {
    int data = 0;
    ~ManagedResource() { /* Resource cleanup */ }
};

// C++14+ initialization
std::unique_ptr<ManagedResource> p1 =
    std::make_unique<ManagedResource>();

// Accessing the owned object
p1->data = 42;

// Exclusive Ownership: Transfer ownership via move
std::unique_ptr<ManagedResource> p2 = std::move(p1);

// p1 is now null, p2 owns the resource
bool is_p1_null = (p1 == nullptr);

// Access raw pointer (for interfacing C APIs)
ManagedResource* raw = p2.get();

// Deletion occurs automatically when p2 goes out of scope.
